from fractions import Fraction
TOPICS=[]
def topic(subject,skill,ru,kk,rows):
    assert len(rows)==4
    TOPICS.append((subject,skill,[ru,kk],rows))
def ex(ru,kk,options,why_ru,why_kk):
    return ([ru,kk],options,[why_ru,why_kk])
def num(ru,kk,answer,wrong,why_ru,why_kk):
    return ex(ru,kk,list(map(str,[answer]+wrong)),why_ru,why_kk)
