def build_topics():
    if not TOPICS:
        numeric_topics()
        verbal_topics()
    return TOPICS

def knowledge(subject,skill,ru,kk,rows):
    # Four different facts in one topic: two diagnostics and two practice items.
    assert len({r[2] for r in rows})==4
    assert len({r[3] for r in rows})==4
    exercises=[]
    for i,(prompt_ru,prompt_kk,answer_ru,answer_kk,why_ru,why_kk) in enumerate(rows):
        others=[r for j,r in enumerate(rows) if j!=i]
        wrong=FACT_DISTRACTORS.get((subject,skill))
        choices=([[answer_ru]+wrong[i][0].split('|'),[answer_kk]+wrong[i][1].split('|')]
                 if wrong else [[answer_ru]+[r[2] for r in others],[answer_kk]+[r[3] for r in others]])
        exercises.append(ex(prompt_ru,prompt_kk,choices,why_ru,why_kk))
    topic(subject,skill,ru,kk,exercises)

